var supportedLanguageCodeSet = new Set(supportedLanguageCodes.map((code) => code.toLowerCase()));
var primaryLanguageCodes = Object.fromEntries(
  supportedLanguageCodes.reduce((entries, code) => {
    const normalized = code.toLowerCase();
    const base = normalized.split("-")[0];
    if (!entries.some(([key]) => key === normalized)) entries.push([normalized, code]);
    if (!entries.some(([key]) => key === base)) entries.push([base, code]);
    return entries;
  }, [])
);
